('sc-001', 'scr-001', 'add', 'sk-fs-dp-dic', 'FS-DP-01', 'Digital I&C fundamentals', 'أساسيات أجهزة القياس والتحكم الرقمية', 'Added "Digital I&C fundamentals"', 'أُضيفت «أساسيات أجهزة القياس والتحكم الرقمية»', '{}'::jsonb, '{"name_en":"Digital I&C fundamentals","name_ar":"أساسيات أجهزة القياس والتحكم الرقمية","key_level":2,"lifecycle":"growing","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2028-07-01","level_essence_en":"Explains how digital instrumentation and control differs from analogue, including software qualification, diversity and common-cause failure.","level_essence_ar":"يشرح كيف تختلف أجهزة القياس والتحكم الرقمية عن التناظرية، بما في ذلك تأهيل البرمجيات والتنوّع وأعطال السبب المشترك.","alt_labels_en":["Digital instrumentation basics","Software-based protection systems"],"alt_labels_ar":["أساسيات الأجهزة الرقمية","أنظمة الحماية القائمة على البرمجيات"]}'::jsonb, null, 1, array['sk-fs-dp-dic']::text[], null, '2026-06-16', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','hr_director']::text[], 'instructor', '2026-06-16T11:00:00Z', null, '[{"label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","url":"https://www.iaea.org/node/97473"},{"label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"},{"label":"ENEC · Barakah technology","url":"https://www.enec.ae/barakah-plant/technology/"}]'::jsonb),
('sc-002', 'scr-002', 'add', 'sk-fs-dp-robotics', 'FS-DP-02', 'Robotics and remote inspection', 'الروبوتات والفحص عن بُعد', 'Added "Robotics and remote inspection"', 'أُضيفت «الروبوتات والفحص عن بُعد»', '{}'::jsonb, '{"name_en":"Robotics and remote inspection","name_ar":"الروبوتات والفحص عن بُعد","key_level":2,"lifecycle":"emerging","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2027-08-01","level_essence_en":"Plans and supervises robot or drone inspections that cut dose and confined-space entry, and judges the quality of what they record.","level_essence_ar":"يخطط لعمليات الفحص بالروبوتات أو الطائرات المسيّرة التي تقلّل الجرعة الإشعاعية ودخول الأماكن الضيقة ويشرف عليها، ويقيّم جودة ما تسجّله.","alt_labels_en":["Crawler and drone inspection","Remote handling"],"alt_labels_ar":["الفحص بالروبوتات الزاحفة والطائرات المسيّرة","المناولة عن بُعد"]}'::jsonb, null, 1, array['sk-fs-dp-robotics']::text[], null, '2026-06-16', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','hr_director']::text[], 'instructor', '2026-06-16T11:00:00Z', null, '[{"label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"},{"label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"},{"label":"ENEC · TII and ASPIRE autonomous aerial systems (Jan 2026)","url":"https://www.enec.ae/en/news/latest-news/enec-tii-and-aspire-collaborate-on-autonomous-aerial-systems-to-enhance-critical-infrastructure/"}]'::jsonb),
