('sc-027', 'scr-027', 'add', 'sk-fs-ai-prompt', 'FS-AI-03', 'Prompt and agent literacy', 'الإلمام بصياغة الأوامر والوكلاء الذكيين', 'Added "Prompt and agent literacy"', 'أُضيفت «الإلمام بصياغة الأوامر والوكلاء الذكيين»', '{}'::jsonb, '{"name_en":"Prompt and agent literacy","name_ar":"الإلمام بصياغة الأوامر والوكلاء الذكيين","key_level":2,"lifecycle":"emerging","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2027-09-01","level_essence_en":"Writes clear, bounded instructions for AI assistants and agents, sets limits on what an agent may do, and reviews each step it takes.","level_essence_ar":"يكتب تعليمات واضحة ومحددة لمساعدي الذكاء الاصطناعي ووكلائه، ويضع حدوداً لما يجوز للوكيل فعله، ويراجع كل خطوة يتخذها.","alt_labels_en":["Prompt writing","Working with AI agents"],"alt_labels_ar":["كتابة الأوامر","العمل مع الوكلاء الذكيين"]}'::jsonb, null, 1, array['sk-fs-ai-prompt']::text[], null, '2026-08-11', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','admin']::text[], 'employee', '2026-08-11T11:00:00Z', null, '[{"label":"ADNOC AI upskilling and EGA Academy","url":"https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42"},{"label":"EU AI Act Article 4 AI-literacy repository and UNESCO AI Competency Frameworks","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"}]'::jsonb),
('sc-028', 'scr-028', 'add', 'sk-fs-ai-dataeng', 'FS-AI-04', 'Data engineering basics', 'أساسيات هندسة البيانات', 'Added "Data engineering basics"', 'أُضيفت «أساسيات هندسة البيانات»', '{}'::jsonb, '{"name_en":"Data engineering basics","name_ar":"أساسيات هندسة البيانات","key_level":2,"lifecycle":"growing","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2027-10-01","level_essence_en":"Builds simple, documented data pipelines from approved sources, with versioned inputs and checks that others can rerun.","level_essence_ar":"يبني خطوط بيانات بسيطة وموثّقة من مصادر معتمدة، بمدخلات مرقّمة الإصدارات وفحوص يمكن للآخرين إعادة تشغيلها.","alt_labels_en":["Data pipelines","Data preparation"],"alt_labels_ar":["خطوط البيانات","تحضير البيانات"]}'::jsonb, null, 1, array['sk-fs-ai-dataeng']::text[], null, '2026-08-11', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','admin']::text[], 'employee', '2026-08-11T11:00:00Z', null, '[{"label":"LinkedIn Economic Graph: Skills on the Rise and Work Change","url":"https://economicgraph.linkedin.com/research"},{"label":"DigComp 2.2 / 3.0 digital competence framework","url":"https://joint-research-centre.ec.europa.eu/scientific-activities-z/education-and-training/digital-transformation-education/digital-competence-framework-citizens-digcomp_en"}]'::jsonb),
('sc-029', 'scr-029', 'add', 'sk-fs-ai-plantdata', 'FS-AI-05', 'Plant-data quality', 'جودة بيانات المحطة', 'Added "Plant-data quality"', 'أُضيفت «جودة بيانات المحطة»', '{}'::jsonb, '{"name_en":"Plant-data quality","name_ar":"جودة بيانات المحطة","key_level":2,"lifecycle":"growing","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2027-11-01","level_essence_en":"Spots drift, gaps and bad tags in plant historian data, records where each data set came from and keeps data fit for safety analysis.","level_essence_ar":"يكتشف الانحراف والفجوات والوسوم الخاطئة في البيانات التاريخية للمحطة، ويسجّل مصدر كل مجموعة بيانات، ويحافظ على صلاحيتها لتحليلات السلامة.","alt_labels_en":["Data integrity","Sensor data validation"],"alt_labels_ar":["سلامة البيانات","التحقق من بيانات المستشعرات"]}'::jsonb, null, 1, array['sk-fs-ai-plantdata']::text[], null, '2026-08-11', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','admin']::text[], 'employee', '2026-08-11T11:00:00Z', null, '[{"label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"},{"label":"DigComp 2.2 / 3.0 digital competence framework","url":"https://joint-research-centre.ec.europa.eu/scientific-activities-z/education-and-training/digital-transformation-education/digital-competence-framework-citizens-digcomp_en"}]'::jsonb),
('sc-030', 'scr-030', 'add', 'sk-fs-ai-automation', 'FS-AI-06', 'Automation design', 'تصميم الأتمتة', 'Added "Automation design"', 'أُضيفت «تصميم الأتمتة»', '{}'::jsonb, '{"name_en":"Automation design","name_ar":"تصميم الأتمتة","key_level":2,"lifecycle":"emerging","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2027-12-01","level_essence_en":"Designs small automations for administrative workflows with a named owner, a fallback and a test record, never for plant control.","level_essence_ar":"يصمّم أتمتة صغيرة لسير العمل الإداري مع مالك محدد وخطة بديلة وسجل اختبار، ولا يستخدمها أبداً في التحكم بالمحطة.","alt_labels_en":["Workflow automation","Low-code automation"],"alt_labels_ar":["أتمتة سير العمل","الأتمتة منخفضة البرمجة"]}'::jsonb, null, 1, array['sk-fs-ai-automation']::text[], null, '2026-08-11', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','admin']::text[], 'employee', '2026-08-11T11:00:00Z', null, '[{"label":"ADNOC AI upskilling and EGA Academy","url":"https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42"},{"label":"Corporate reskilling programmes: AT&T, IBM, Schneider/Unilever, Google AI Essentials","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/"}]'::jsonb),
('sc-031', 'scr-031', 'add', 'sk-fs-ai-xr', 'FS-AI-07', 'AR and VR for training and work', 'الواقع المعزّز والافتراضي في التدريب والعمل', 'Added "AR and VR for training and work"', 'أُضيفت «الواقع المعزّز والافتراضي في التدريب والعمل»', '{}'::jsonb, '{"name_en":"AR and VR for training and work","name_ar":"الواقع المعزّز والافتراضي في التدريب والعمل","key_level":2,"lifecycle":"emerging","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2027-07-01","level_essence_en":"Uses augmented and virtual reality for walk-downs and practice, and knows where a simulator or the real plant is still required.","level_essence_ar":"يستخدم الواقع المعزّز والافتراضي في الجولات التفقدية والتدريب، ويعرف متى يظل المحاكي أو المحطة الفعلية ضرورياً.","alt_labels_en":["Immersive learning","Extended reality"],"alt_labels_ar":["التعلّم الغامر","الواقع الممتد"]}'::jsonb, null, 1, array['sk-fs-ai-xr']::text[], null, '2026-08-11', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','admin']::text[], 'employee', '2026-08-11T11:00:00Z', null, '[{"label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"},{"label":"DigComp 2.2 / 3.0 digital competence framework","url":"https://joint-research-centre.ec.europa.eu/scientific-activities-z/education-and-training/digital-transformation-education/digital-competence-framework-citizens-digcomp_en"}]'::jsonb),
('sc-032', 'scr-032', 'add', 'sk-fs-ai-twin', 'FS-AI-08', 'Digital twin validation', 'التحقق من صحة التوائم الرقمية', 'Added "Digital twin validation"', 'أُضيفت «التحقق من صحة التوائم الرقمية»', '{}'::jsonb, '{"name_en":"Digital twin validation","name_ar":"التحقق من صحة التوائم الرقمية","key_level":3,"lifecycle":"emerging","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2027-08-01","level_essence_en":"Compares twin predictions with plant behaviour, records where the model is valid and flags when it drifts out of its range.","level_essence_ar":"يقارن تنبؤات التوأم الرقمي بسلوك المحطة، ويسجّل النطاق الذي يصحّ فيه النموذج، وينبّه عند خروجه عن نطاقه.","alt_labels_en":["Model validation","Twin-to-plant comparison"],"alt_labels_ar":["التحقق من النماذج","مقارنة التوأم بالمحطة"]}'::jsonb, null, 1, array['sk-fs-ai-twin']::text[], null, '2026-08-11', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','admin']::text[], 'employee', '2026-08-11T11:00:00Z', null, '[{"label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb),
('sc-033', 'scr-033', 'add', 'sk-fs-ai-anomaly', 'FS-AI-09', 'Anomaly triage with AI alerts', 'فرز الحالات الشاذة باستخدام تنبيهات الذكاء الاصطناعي', 'Added "Anomaly triage with AI alerts"', 'أُضيفت «فرز الحالات الشاذة باستخدام تنبيهات الذكاء الاصطناعي»', '{}'::jsonb, '{"name_en":"Anomaly triage with AI alerts","name_ar":"فرز الحالات الشاذة باستخدام تنبيهات الذكاء الاصطناعي","key_level":2,"lifecycle":"emerging","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2027-09-01","level_essence_en":"Sorts AI-generated anomaly alerts into act, watch and dismiss, with reasons, and feeds the outcome back to the model owner.","level_essence_ar":"يفرز تنبيهات الحالات الشاذة التي يولّدها الذكاء الاصطناعي إلى: تصرّف، أو مراقبة، أو تجاهل، مع الأسباب، ويعيد النتيجة إلى مالك النموذج.","alt_labels_en":["Alert triage","Predictive maintenance alerts"],"alt_labels_ar":["فرز التنبيهات","تنبيهات الصيانة التنبؤية"]}'::jsonb, null, 1, array['sk-fs-ai-anomaly']::text[], null, '2026-08-11', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','admin']::text[], 'employee', '2026-08-11T11:00:00Z', null, '[{"label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb),
('sc-034', 'scr-034', 'add', 'sk-fs-ai-data-care', 'FS-AI-10', 'Responsible data handling', 'التعامل المسؤول مع البيانات', 'Added "Responsible data handling"', 'أُضيفت «التعامل المسؤول مع البيانات»', '{}'::jsonb, '{"name_en":"Responsible data handling","name_ar":"التعامل المسؤول مع البيانات","key_level":2,"lifecycle":"growing","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2027-10-01","level_essence_en":"Handles personal and commercial data on a need-to-know basis, minimises what is shared and knows how to report a data mistake.","level_essence_ar":"يتعامل مع البيانات الشخصية والتجارية على أساس الحاجة إلى المعرفة، ويقلّل ما يُشارك، ويعرف كيف يبلّغ عن خطأ في البيانات.","alt_labels_en":["Data protection","Privacy by design"],"alt_labels_ar":["حماية البيانات","الخصوصية في التصميم"]}'::jsonb, null, 1, array['sk-fs-ai-data-care']::text[], null, '2026-08-11', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','admin']::text[], 'employee', '2026-08-11T11:00:00Z', null, '[{"label":"EU AI Act Article 4 AI-literacy repository and UNESCO AI Competency Frameworks","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"},{"label":"DigComp 2.2 / 3.0 digital competence framework","url":"https://joint-research-centre.ec.europa.eu/scientific-activities-z/education-and-training/digital-transformation-education/digital-competence-framework-citizens-digcomp_en"}]'::jsonb),
('sc-035', 'scr-035', 'add', 'sk-fs-gr-lifecycle', 'FS-GR-01', 'Lifecycle carbon assessment', 'تقييم الكربون على امتداد دورة الحياة', 'Added "Lifecycle carbon assessment"', 'أُضيفت «تقييم الكربون على امتداد دورة الحياة»', '{}'::jsonb, '{"name_en":"Lifecycle carbon assessment","name_ar":"تقييم الكربون على امتداد دورة الحياة","key_level":2,"lifecycle":"emerging","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2028-11-01","level_essence_en":"Estimates the lifecycle emissions of an energy option or project with a stated method and compares it fairly with alternatives.","level_essence_ar":"يقدّر انبعاثات خيار طاقة أو مشروع على امتداد دورة حياته بمنهجية معلنة، ويقارنه بالبدائل مقارنة منصفة.","alt_labels_en":["Life-cycle assessment","Embodied carbon"],"alt_labels_ar":["تقييم دورة الحياة","الكربون المتضمَّن"]}'::jsonb, null, 1, array['sk-fs-gr-lifecycle']::text[], null, '2026-08-25', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','hr_director']::text[], 'instructor', '2026-08-25T11:00:00Z', null, '[{"label":"GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp"},{"label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"},{"label":"ENEC · Climate change","url":"https://www.enec.ae/about-us/overview/climate-change/"}]'::jsonb)
